CREATE TABLE `test_case` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL,
  `case_code` varchar(64) NOT NULL COMMENT '台账编号，如 PERF-IPERF-200G-001',
  `external_id` varchar(128) DEFAULT NULL COMMENT '源表用例编号（对外业务键，幂等依据）',
  `title` varchar(256) NOT NULL,
  `case_kind` varchar(32) DEFAULT NULL COMMENT 'func/perf/rdma/...',
  `source_type` varchar(16) NOT NULL DEFAULT 'ledger' COMMENT 'ledger/script',
  `priority` varchar(8) DEFAULT NULL,
  `safety_level` varchar(8) NOT NULL DEFAULT 'LX' COMMENT '执行安全级：L0 只读 / L1 可逆写 / L2 高危 / LX 未判定（ADR-0013）',
  `domain_tag` varchar(64) DEFAULT NULL COMMENT '技术域标签',
  `status` tinyint NOT NULL DEFAULT '1',
  `description` text,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `updated_by` bigint DEFAULT NULL,
  `precondition` text,
  `expected` text,
  `review_status` varchar(16) NOT NULL DEFAULT 'draft' COMMENT 'draft/pending/approved/rejected',
  `review_comment` varchar(512) DEFAULT NULL,
  `reviewed_by` bigint DEFAULT NULL,
  `reviewed_at` datetime(3) DEFAULT NULL,
  `source` varchar(32) NOT NULL DEFAULT 'import' COMMENT 'import/manual/api',
  `capability` varchar(64) DEFAULT NULL COMMENT '能力维度，如 roce-connectivity / pfc-backpressure',
  `category_l2` varchar(128) DEFAULT NULL COMMENT '二级分类',
  `source_priority` varchar(16) DEFAULT NULL COMMENT '源表优先级原值（T0/T1/T2 或 P0/P1/P2），保留不覆盖',
  `case_class` varchar(64) DEFAULT NULL COMMENT '用例分类',
  `test_category` varchar(64) DEFAULT NULL COMMENT '测试归类',
  `ed202_coverage` text COMMENT 'ED202 覆盖情况 / CX7 结果记录 / 测试资源',
  `source_sheet` varchar(128) DEFAULT NULL COMMENT '来源 sheet 名（UECGSE适配 83 条可追溯）',
  `category_l1` varchar(128) DEFAULT NULL COMMENT '一级分类（公共库筛选维度）',
  `content_sha` char(64) DEFAULT NULL COMMENT '内容指纹（sha256，幂等与导出缓存依据）',
  `lifecycle_status` varchar(16) NOT NULL DEFAULT 'active' COMMENT 'active / deprecated',
  `version_no` int NOT NULL DEFAULT '1' COMMENT '内容版本号，更新即 +1',
  `a_side_command` text COMMENT 'A端命令（FR-49-05）',
  `b_side_command` text COMMENT 'B端命令（FR-49-05）',
  `switch_config` text COMMENT '交换机配置（FR-49-05）',
  `test_result` varchar(512) DEFAULT NULL COMMENT '测试结果（FR-49-05）',
  `test_resource` text COMMENT '测试资源（原误并入 ed202_coverage，FR-49-06 拆为独立列）',
  `category_l1_id` bigint DEFAULT NULL COMMENT '逻辑外键 → case_category.id（一级分类）',
  `category_l2_id` bigint DEFAULT NULL COMMENT '逻辑外键 → case_category.id（二级分类）',
  `category_match_review` varchar(16) DEFAULT NULL COMMENT 'AMBIGUOUS = 字符串非唯一匹配，待人工复核；唯一匹配回填后保持 NULL',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_test_case_project_code` (`project_id`,`case_code`),
  KEY `idx_test_case_domain` (`project_id`,`domain_tag`),
  KEY `idx_test_case_review` (`project_id`,`review_status`),
  KEY `idx_test_case_priority` (`project_id`,`priority`),
  KEY `idx_test_case_capability` (`project_id`,`capability`),
  KEY `idx_test_case_safety` (`project_id`,`safety_level`),
  KEY `idx_test_case_source_sheet` (`project_id`,`source_sheet`),
  KEY `idx_case_project_updated` (`project_id`,`updated_at`),
  KEY `idx_case_project_id` (`project_id`,`id`),
  KEY `idx_test_case_category_l1` (`project_id`,`category_l1`,`lifecycle_status`),
  KEY `idx_test_case_external` (`project_id`,`external_id`),
  KEY `idx_test_case_category_ids` (`project_id`,`category_l1_id`,`category_l2_id`),
  KEY `idx_test_case_category_review` (`project_id`,`category_match_review`),
  CONSTRAINT `fk_test_case_project` FOREIGN KEY (`project_id`) REFERENCES `project` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1862 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用例台账';
